import base64
import os
import six


class RDModeInterface21B(object):

    def set_vendor_file(self, vendor_file, timeout=300):
        """
        Set vendor file.

        :param str vendor_file: xml file or path to xml file.
        :param float timeout: Time to wait for positive procedure result
        :return: str: BTS response containing operation result alongside validation output.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setVendorFile.html
        """
        if os.path.isfile(vendor_file):
            with open(vendor_file, 'r') as f:
                vendor_file = f.read()

        six_vendor_file = six.b(vendor_file)
        b64_vendor_file = base64.b64encode(six_vendor_file)
        parameters = {"inputFileContent": b64_vendor_file.decode("utf-8")}

        return self._api_client.execute_procedure("setVendorFile", parameters, timeout)

    def download_vendor_file(self, target_file_name, timeout=60):
        """
        Download vendor file.

        :param str target_file_name: target vendor_file filename.
        :param int timeout: Time to wait for positive procedure result
        :return: str: Response, one of: ["Waiting for response", "Rejected", "Failed", "Succeeded"].

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-downloadVendorFile.html
        """

        return self._api_client.execute_infomodel_request("downloadVendorFile", {}, timeout=timeout,
                                                          output_file_name=target_file_name)
